/**
 * Local database (expo-sqlite). Shaped so a server sync can be added later
 * without migrating data: ids are UUIDs created on the device, and every row
 * has updated_at / synced_at so unsynced changes can be found.
 *
 * Schema changes: add a new entry to MIGRATIONS (never edit an old one).
 */
import { openDatabaseSync } from 'expo-sqlite';

export const db = openDatabaseSync('neuromind.db');

/** UUID v4 generated by SQLite's secure random source (no extra package needed). */
export const SQL_UUID = `(lower(hex(randomblob(4))) || '-' || lower(hex(randomblob(2))) || '-4' ||
  substr(lower(hex(randomblob(2))), 2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) ||
  substr(lower(hex(randomblob(2))), 2) || '-' || lower(hex(randomblob(6))))`;

const MIGRATIONS: string[] = [
  // 1 — initial schema
  `
  CREATE TABLE users (
    id             TEXT PRIMARY KEY NOT NULL,
    server_user_id TEXT,                       -- filled in when login arrives
    created_at     TEXT NOT NULL
  );

  CREATE TABLE checkins (
    id              TEXT PRIMARY KEY NOT NULL,
    user_id         TEXT NOT NULL REFERENCES users(id),
    period          TEXT NOT NULL,             -- e.g. '2026-11', for display/grouping
    status          TEXT NOT NULL CHECK (status IN ('in_progress', 'completed', 'abandoned')),
    started_at      TEXT NOT NULL,
    completed_at    TEXT,
    content_version TEXT NOT NULL,             -- which version of the questions was asked
    updated_at      TEXT NOT NULL,
    synced_at       TEXT
  );
  CREATE INDEX checkins_by_user_start ON checkins (user_id, started_at);

  CREATE TABLE answers (
    id           TEXT PRIMARY KEY NOT NULL,
    checkin_id   TEXT NOT NULL REFERENCES checkins(id) ON DELETE CASCADE,
    dimension_id INTEGER NOT NULL,
    question_id  TEXT NOT NULL,
    value        INTEGER NOT NULL CHECK (value BETWEEN 0 AND 10),
    answered_at  TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    synced_at    TEXT,
    UNIQUE (checkin_id, question_id)           -- one answer per question per check-in
  );

  CREATE TABLE dimension_progress (
    checkin_id   TEXT NOT NULL REFERENCES checkins(id) ON DELETE CASCADE,
    dimension_id INTEGER NOT NULL,
    completed_at TEXT,
    updated_at   TEXT NOT NULL,
    synced_at    TEXT,
    PRIMARY KEY (checkin_id, dimension_id)
  );
  `,
];

function migrate() {
  db.execSync('PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;');
  const row = db.getFirstSync<{ user_version: number }>('PRAGMA user_version');
  const current = row?.user_version ?? 0;
  for (let v = current; v < MIGRATIONS.length; v++) {
    db.withTransactionSync(() => {
      db.execSync(MIGRATIONS[v]);
      db.execSync(`PRAGMA user_version = ${v + 1}`);
    });
  }
}

migrate();
